import ajax from '@/utils/ajax';
import { makeObservable, action, observable } from 'mobx';
import { PromptTemplateItem } from './interface';




class Store {

    
    @observable list: PromptTemplateItem[] = []
    @action setList = (list) => {
        this.list = list;
    }

    @observable loading = false;
    @action setLoading = (bool) => {
        this.loading = bool;
    }


    // 获取 PromptTemplate 列表
    getPromptTemplate = () => {
        this.setLoading(true);
        ajax.post('/apijson/get', {
            "PromptTemplate[]": {
                "count": 0,
                PromptTemplate: {

                }
            }
        }).then((res) => {
            this.setList(res.PromptTemplate.map((o) => {
                return {
                    ...o,
                    content: JSON.parse(o.content || '{}')
                }
            }));
        }).finally(() => {
            this.setLoading(false);
        })
    }



    init = () => {
        this.getPromptTemplate();
    }



    @observable addVisible = false;
    @action setAddVisible = (bool) => {
        this.addVisible = bool;
    }
    item: any = null;
    // 添加模版
    addTemplate = () => {
        this.item = null;
        this.setAddVisible(true);
    }

    // 编辑模版
    editTemplate = (item) => {
        this.item = item
        this.setAddVisible(true);
    }

    constructor(){
        makeObservable(this)
    }
}


export default new Store();